use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclenum! {
# [doc = " `imara-diff` supports multiple different algorithms"] # [doc = " for computing an edit sequence."] # [doc = " These algorithms have different performance and all produce different output."] # [derive (Debug , PartialEq , Eq , Clone , Copy , Default)] pub enum Algorithm { # [doc = " A variation of the [`patience` diff algorithm described by Bram Cohen's blog post](https://bramcohen.livejournal.com/73318.html)"] # [doc = " that uses a histogram to find the least common LCS."] # [doc = " Just like the `patience` diff algorithm, this algorithm usually produces"] # [doc = " more human readable output then myers algorithm."] # [doc = " However compared to the `patience` diff algorithm (which is slower then myers algorithm),"] # [doc = " the Histogram algorithm performs much better."] # [doc = ""] # [doc = " The implementation here was originally ported from `git` but has been significantly"] # [doc = " modified to improve performance."] # [doc = " As a result it consistently **performs better then myers algorithm** (5%-100%) over"] # [doc = " a wide variety of test data. For example a benchmark of diffing linux kernel commits is shown below:"] # [cfg_attr (doc , doc = concat ! ("<img width=\"600\" class=\"figure\" src=\"data:image/svg+xml;base64," , include_str ! ("../plots/linux_speedup.svg.base64") , "\"></img>"))] # [doc = ""] # [doc = " For pathological subsequences that only contain highly repeating tokens (64+ occurrences)"] # [doc = " the algorithm falls back on Myers algorithm (with heuristics) to avoid quadratic behavior."] # [doc = ""] # [doc = " Compared to Myers algorithm, the Histogram diff algorithm is more focused on providing"] # [doc = " human readable diffs instead of minimal diffs. In practice this means that the edit-sequences"] # [doc = " produced by the histogram diff are often longer then those produced by Myers algorithm."] # [doc = ""] # [doc = " The heuristic used by the histogram diff does not work well for inputs with small (often repeated)"] # [doc = " tokens. For example **character diffs do not work well** as most (english) text is made up of"] # [doc = " a fairly small set of characters. The `Histogram` algorithm will automatically these cases and"] # [doc = " fallback to Myers algorithm. However this detection has a nontrivial overhead, so"] # [doc = " if its known upfront that the sort of tokens is very small `Myers` algorithm should"] # [doc = " be used instead."] # [default] Histogram , # [doc = " An implementation of the linear space variant of"] # [doc = " [Myers  `O((N+M)D)` algorithm](http://www.xmailserver.org/diff2.pdf)."] # [doc = " The algorithm is enhanced with preprocessing that removes"] # [doc = " tokens that don't occur in the other file at all."] # [doc = " Furthermore two heuristics to the middle snake search are implemented"] # [doc = " that ensure reasonable runtime (mostly linear time complexity) even for large files."] # [doc = ""] # [doc = " Due to the divide and conquer nature of the algorithm"] # [doc = " the edit sequenced produced are still fairly small even when the middle snake"] # [doc = " search is aborted by a heuristic."] # [doc = " However, the produced edit sequences are not guaranteed to be fully minimal."] # [doc = " If that property is vital to you, use the `MyersMinimal` algorithm instead."] # [doc = ""] # [doc = " The implementation (including the preprocessing) are mostly"] # [doc = " ported from `git` and `gnu-diff` where Myers algorithm is used"] # [doc = " as the default diff algorithm."] # [doc = " Therefore the used heuristics have been heavily battle tested and"] # [doc = " are known to behave well over a large variety of inputs"] Myers , # [doc = " Same as `Myers` but the early abort heuristics are disabled to guarantee"] # [doc = " a minimal edit sequence."] # [doc = " This can mean significant slowdown in pathological cases."] MyersMinimal , }
}